class Solution {
    public int arrangeCoins(int n) {
        long lo = 1, hi = n;
        while (lo <= hi) {
            long mid = lo + (hi - lo) / 2;
            if (mid * (mid + 1) / 2 <= n) lo = mid + 1;
            else hi = mid - 1;
        }
        return (int) hi;
    }
}

